# Fall back to well-formed XML parse
python3 -c "
import xml.etree.ElementTree as ET
tree = ET.parse('/work/output/artifacts/skill-bpmn-contract-variant-wrappers/ContractVariantsBpmn/ContractVariantsBpmn.bpmn')
root = tree.getroot()
print('XML well-formed: OK')
ns = {'bpmn':'http://www.omg.org/spec/BPMN/20100524/MODEL','bpmndi':'http://www.omg.org/spec/BPMN/20100524/DI'}
proc = root.find('bpmn:process', ns)
diag = root.find('bpmndi:BPMNDiagram', ns)
print(f'Process id: {proc.get(\"id\")}')
plane = diag.find('bpmndi:BPMNPlane', ns)
shapes = plane.findall('bpmndi:BPMNShape', ns)
edges = plane.findall('bpmndi:BPMNEdge', ns)
print(f'Shapes: {len(shapes)}, Edges: {len(edges)}')
# check all sourceRef/targetRef resolve
ids = {el.get('id') for el in proc.iter() if el.get('id')}
flows = proc.findall('bpmn:sequenceFlow', ns)
errors = []
for f in flows:
    if f.get('sourceRef') not in ids: errors.append(f'dangling sourceRef {f.get(\"sourceRef\")}')
    if f.get('targetRef') not in ids: errors.append(f'dangling targetRef {f.get(\"targetRef\")}')
if errors:
    for e in errors: print('ERROR:', e)
else:
    print('All sourceRef/targetRef resolved OK')
# check all bpmnElements in shapes/edges resolve
shape_refs = {s.get('bpmnElement') for s in shapes}
edge_refs = {e.get('bpmnElement') for e in edges}
flow_ids = {f.get('id') for f in flows}
node_ids = ids - flow_ids
for ref in shape_refs:
    if ref not in ids: print('ERROR: shape bpmnElement', ref, 'not found')
for ref in edge_refs:
    if ref not in ids: print('ERROR: edge bpmnElement', ref, 'not found')
print('Shape/edge reference check done')
"
